	private function dc($key){ $p=explode('-',trim($key)); return count($p)>1?sanitize_key(end($p)):''; }
	private function api($method,$path,$body=null){ $s=$this->settings();$key=trim($s['api_key']);$dc=$this->dc($key);if(!$key||!$dc)return new WP_Error('emo_api','Enter a valid Mailchimp API key.');$a=['method'=>strtoupper($method),'timeout'=>25,'headers'=>['Authorization'=>'Basic '.base64_encode('wordpress:'.$key),'Content-Type'=>'application/json']];if($body!==null)$a['body']=wp_json_encode($body);$r=wp_remote_request('https://'.$dc.'.api.mailchimp.com/3.0/'.ltrim($path,'/'),$a);if(is_wp_error($r))return$r;$code=wp_remote_retrieve_response_code($r);$d=json_decode(wp_remote_retrieve_body($r),true);if($code<200||$code>=300)return new WP_Error('emo_mailchimp',$d['detail']??'Mailchimp API request failed.',['status'=>$code]);return is_array($d)?$d:[]; }
	private function audiences(){ $r=$this->api('GET','lists?count=100&fields=lists.id,lists.name,lists.stats.member_count'); return is_wp_error($r)?$r:($r['lists']??[]); }
